/**
 * @easyjobs/registry — verified companies (CompanyTarget[]) with the exact ATS + token the scrapers need.
 * Data: ../data/companies.json (generated by scripts/verify.ts, sorted by slug). Token formats: prompts.md §0.6.
 */
import { readFileSync } from "node:fs";
import type { AtsType, CompanyTarget } from "@easyjobs/contract";
import { CURATED_ALIASES } from "./aliases";
import { createCompanyIndex, type CompanyMatch } from "./match";

export type { CompanyMatch, MatchVia, CompanyIndex, AliasTable } from "./match";
export { createCompanyIndex } from "./match";
export { validateCompanyTarget, validateRegistry, SLUG_RE } from "./validate";
export { detectAts, detectAtsFromUrl, isValidToken, TOKEN_RULES, type AtsDetection } from "./ats";
export { normalizeName, coreName, compactName, normalizeDomain, namesMatch } from "./normalize";

function loadCompanies(): CompanyTarget[] {
  const url = new URL("../data/companies.json", import.meta.url);
  let parsed: unknown;
  try {
    parsed = JSON.parse(readFileSync(url, "utf8"));
  } catch (e) {
    throw new Error(`@easyjobs/registry: cannot read ${url.pathname}: ${e instanceof Error ? e.message : String(e)}`);
  }
  if (!Array.isArray(parsed)) throw new Error("@easyjobs/registry: companies.json must be an array");
  return parsed as CompanyTarget[];
}

/** Every verified company, sorted by slug. Entries are frozen — copy before modifying. */
export const companies: readonly CompanyTarget[] = Object.freeze(loadCompanies().map((c) => Object.freeze(c)));

/**
 * Alias names per slug ("tcs" → ["Tata Consultancy Services", …]): the curated table in ./aliases.ts plus each
 * entry's `extra.aliases` (legal entities / former names from the candidate lists). Only slugs in `companies`.
 */
export const aliases: Readonly<Record<string, readonly string[]>> = Object.freeze(
  Object.fromEntries(
    companies
      .map((c) => {
        const extra = Array.isArray(c.extra?.["aliases"]) ? (c.extra["aliases"] as unknown[]).filter((a): a is string => typeof a === "string") : [];
        const all = [...new Set([...(CURATED_ALIASES[c.slug] ?? []), ...extra])].filter((a) => a !== c.name);
        return [c.slug, Object.freeze(all)] as const;
      })
      .filter(([, list]) => list.length > 0),
  ),
);

const bySlug = new Map(companies.map((c) => [c.slug, c] as const));
const index = createCompanyIndex(companies, aliases);

export function getCompany(slug: string): CompanyTarget | null {
  return bySlug.get(slug) ?? bySlug.get(slug.trim().toLowerCase()) ?? null;
}

/** Targets for one or more ATS types, in slug order. */
export function targetsByAts(ats: AtsType | readonly AtsType[]): CompanyTarget[] {
  const wanted = new Set<AtsType>(typeof ats === "string" ? [ats] : ats);
  return companies.filter((c) => wanted.has(c.ats));
}

/**
 * Best registry match for a company name, alias, domain, slug or ATS/careers URL; null when unsure.
 *   findCompany("Tata Consultancy Services Ltd") → TCS · findCompany("https://jobs.lever.co/cred") → CRED
 */
export function findCompany(nameOrDomainOrSlug: string | null | undefined): CompanyTarget | null {
  return index.find(nameOrDomainOrSlug);
}

/** Like findCompany, but also says how it matched (slug/ats/domain/name/alias/compact/core/prefix/fuzzy). */
export function matchCompany(nameOrDomainOrSlug: string | null | undefined): CompanyMatch | null {
  return index.match(nameOrDomainOrSlug);
}

export default companies;
